def is_unit3(unit_name='', rows=()):
    name=str(unit_name or '')
    if re.search(r'(?i)\bunit\s*0?3\b|\bcellular\s+energetics\b',name):return True
    texts=' '.join(str(r.get('filename',''))+' '+str(r.get('text',''))[:5000] for r in rows)
    if re.search(r'(?i)\bunit\s*0?3\b|\bcellular\s+energetics\b',texts):return True
    return all(re.search(r'(?i)\b'+s+r'\w*\b',texts) for s in ('enzyme','photosynth','respir'))

def looks_like_objective(term,definition):
    t=str(term or '').strip().lower(); d=str(definition or '').strip().lower()
    if not t or not d:return True
    if re.search(r'\b(explain|describe|identify|analy[sz]e|evaluate|predict|justify|compare|construct|determine|calculate|discuss|design|interpret|model)\b',t):return True
    if '?' in t or '?' in d or len(t.split())>10:return True
    if re.match(r'^(?:lo|ek|objective|learning goal|learning objective|skill|success criteria)\b',t):return True
    return d.startswith(('students will','i can ','you should be able to','learning target'))

def build_questions(count,requested,unit_id,rid):
    if 'mcq' not in requested:
        raise ValueError('High-quality free Unit 3 practice currently supports Multiple choice. Select that question format.')
    by_topic={}
    for q in QUESTIONS:by_topic.setdefault(q[0],[]).append(q)
    for group in by_topic.values():random.shuffle(group)
    output=[];topic_names=list(by_topic)
    while len(output)<count and any(by_topic.values()):
        random.shuffle(topic_names)
        for topic in topic_names:
            if not by_topic[topic] or len(output)>=count:continue
            topic,prompt,options,answer,explanation=by_topic[topic].pop()
            order=list(range(4));random.shuffle(order)
            output.append({'id':rid(),'type':'mcq','topic':topic,'unit_id':unit_id,
                'material_id':None,'source_name':BANK_SOURCE,'prompt':prompt,
                'options':[options[i] for i in order], 'answer':order.index(answer),
                'explanation':explanation})
    return output

def build_cards(count,unit_id):
    choices=list(CARDS);random.shuffle(choices)
    return [{'topic':topic,'front':front,'back':back,'unit_id':unit_id,
             'material_id':None,'source_name':BANK_SOURCE,
             'excerpt':'Original supplemental Unit 3 concept review; not copied from objectives.'}
            for topic,front,back in choices[:count]]
